  const demoActivityRows=()=>[{id:'demo-act-1',kind:'conversation',label:'Conversation',action:'Reviewed Today page spacing',status:'recorded',created_at:demoMoment(0,10,24),details:{title:'Today page spacing review'}},{id:'demo-act-2',kind:'project',label:'Project',action:'Updated mobile layout notes',status:'completed',created_at:demoMoment(0,9,50),details:{title:'Personal AI workspace redesign'}},{id:'demo-act-3',kind:'knowledge',label:'Knowledge',action:'Added Personal AI Product Brief.pdf',status:'recorded',created_at:demoMoment(0,9,15),details:{filename:'Personal AI Product Brief.pdf'}},{id:'demo-act-4',kind:'memory',label:'Memory',action:'Saved project design decision',status:'recorded',created_at:demoMoment(1,16,30),details:{title:'Keep the particle sphere unchanged'}},{id:'demo-act-5',kind:'tasks',label:'Task',action:'Created task: Review project workspace',status:'recorded',created_at:demoMoment(1,14,10),details:{task_title:'Review project workspace'}}];
  const localDateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
