  function bindToday(){document.querySelectorAll('[data-rp-day]').forEach(b=>b.onclick=()=>{const d=state.today.date;d.setDate(d.getDate()+Number(b.dataset.rpDay));state.today.selected=null;loadToday().catch(e=>renderError('today',e))});document.querySelector('[data-rp-today]')?.addEventListener('click',()=>{state.today.date=new Date();state.today.selected=null;loadToday().catch(e=>renderError('today',e))});document.querySelectorAll('[data-rp-jump]').forEach(b=>b.onclick=()=>document.querySelector('.rp-timeline')?.scrollIntoView({behavior:'smooth',block:'start'}));document.querySelectorAll('[data-rp-today-item]').forEach(b=>b.onclick=async()=>{if(preview()){state.today.selected=b.dataset.rpTodayItem;render('today');return}try{const item=state.today.items.find(x=>String(x.id)===b.dataset.rpTodayItem);let record=item;if(item?.source_type==='project_task'){const result=await api('/projects/'+encodeURIComponent(item.project_id));record={...item,...(result.project?.tasks||[]).find(x=>x.id===item.task_id)}}else{const result=await api('/everyday/items/'+encodeURIComponent(b.dataset.rpTodayItem));record=result.item}state.today.items=state.today.items.map(x=>String(x.id)===b.dataset.rpTodayItem?record:x);state.today.selected=b.dataset.rpTodayItem;render('today')}catch(e){showToast(e.message)}});document.querySelectorAll('[data-rp-complete]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const item=state.today.items.find(x=>String(x.id)===b.dataset.rpComplete);if(item?.source_type==='project_task')await api('/projects/'+encodeURIComponent(item.project_id)+'/tasks/'+encodeURIComponent(item.task_id),{method:'PATCH',body:JSON.stringify({status:'done'})});else await api('/everyday/'+encodeURIComponent(b.dataset.rpComplete)+'/complete',{method:'POST',body:'{}'});await loadToday();showToast('Task marked complete')}catch(e){b.disabled=false;showToast(e.message)}})}
  function addToday(){if(preview()){showToast('Preview only — sample records are not saved.');return}let dialog=$('rp-add-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='rp-add-dialog';dialog.className='rp-add-dialog';dialog.innerHTML=`<form id="rp-today-form"><header><h2>Add to Today</h2><button type="button" class="rp-icon-button" data-rp-dialog-close aria-label="Close">×</button></header><label>Type<select name="category"><option value="task">Task</option><option value="meeting">Meeting</option><option value="plan">Plan</option></select></label><label>Title<input name="title" required maxlength="160" autocomplete="off"></label><div class="rp-form-row"><label>Date<input name="day" type="date" required></label><label>Time<input name="time" type="time"></label></div><p class="rp-form-help">A plan is saved as a goal in the existing Everyday store. Meetings need a start time.</p><p class="rp-form-error" role="alert"></p><footer><button type="button" class="rp-button quiet" data-rp-dialog-close>Cancel</button><button type="submit" class="rp-button primary">Save</button></footer></form>`;document.body.append(dialog);dialog.querySelectorAll('[data-rp-dialog-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.onclick=e=>{if(e.target===dialog)dialog.close()};dialog.querySelector('select[name=category]').onchange=e=>{dialog.querySelector('input[name=time]').required=e.target.value==='meeting'}}dialog.querySelector('input[name=day]').value=localDateKey(state.today.date);dialog.querySelector('input[name=time]').value='09:30';dialog.querySelector('.rp-form-error').textContent='';dialog.showModal();const form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const data=new FormData(form),category=String(data.get('category')),title=String(data.get('title')||'').trim(),day=String(data.get('day')),time=String(data.get('time')||'');const err=dialog.querySelector('.rp-form-error');if(!title||!day){err.textContent='Enter a title and date.';return}if(category==='meeting'&&!time){err.textContent='Meetings need a start time.';return}let due=day;if(time){const local=new Date(`${day}T${time}`);if(Number.isNaN(local.getTime())){err.textContent='Enter a valid local date and time.';return}due=local.toISOString()}const save=form.querySelector('[type=submit]');save.disabled=true;err.textContent='Saving…';try{await api('/everyday/items',{method:'POST',body:JSON.stringify({category,title,due_at:due,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'})});dialog.close();await loadToday();showToast('Saved to Today')}catch(e){err.textContent=e.message||'Could not save this item. Your form values are still here.'}finally{save.disabled=false}}}
  async function loadConversations(){const s=state.conversations,epoch=++s.epoch;if(preview())s.rows=demoConversationRows();else{const [result,prefs]=await Promise.all([api(`/conversations?limit=100&include_closed=${s.filter==='archived'}`),api('/preferences').catch(()=>({pinned_sidebar_items:[]}))]);if(epoch!==s.epoch)return;window.uiPreferences={...(window.uiPreferences||{}),...prefs};const pins=Array.isArray(prefs.pinned_sidebar_items)?prefs.pinned_sidebar_items:[];s.rows=(Array.isArray(result.conversations)?result.conversations:[]).map(x=>({...x,pinned:pins.includes('chat:'+x.id)}))}if(!s.selected||!s.rows.some(x=>x.id===s.selected))s.selected=s.rows[0]?.id||null;render('conversations')}
