  function conversationsPage(){const s=state.conversations,q=s.query.toLowerCase().trim();let rows=s.rows.filter(x=>{const archived=!!x.closed_at||x.archived===true,pinned=x.pinned===true;return (s.filter==='archived'?archived:s.filter==='pinned'?pinned&&!archived:!archived)&&(!q||`${x.title||''} ${conversationPreview(x)}`.toLowerCase().includes(q))});rows.sort((a,b)=>s.sort==='oldest'?new Date(a.updated_at)-new Date(b.updated_at):s.sort==='title'?(a.title||'').localeCompare(b.title||''):new Date(b.updated_at)-new Date(a.updated_at));const selected=s.rows.find(x=>x.id===s.selected);const cards=rows.length?rows.map(x=>`<article class="rp-item ${s.selected===x.id?'selected':''}"><button type="button" class="rp-item-main rp-item-select" data-rp-conv="${esc(x.id)}"><span class="rp-item-title">${esc(x.title||'New conversation')}</span><span class="rp-item-desc">${esc(conversationPreview(x)||'No messages yet')}</span><span class="rp-item-meta">${x.context?`<span class="rp-tag teal">${esc(x.context)}</span>`:''}<span>${stamp(x.updated_at)}</span>${x.pinned?'<span aria-label="Pinned">📌 Pinned</span>':''}</span></button><span class="rp-item-actions"><button type="button" class="rp-icon-button" data-rp-pin="${esc(x.id)}" aria-label="${x.pinned?'Unpin':'Pin'} ${esc(x.title||'conversation')}" aria-pressed="${!!x.pinned}">♧</button>${!x.closed_at?`<button type="button" class="rp-icon-button" data-rp-archive="${esc(x.id)}" aria-label="Archive ${esc(x.title||'conversation')}">•••</button>`:''}</span></article>`).join(''):empty(q?'No conversations match your search.':s.filter==='pinned'?'No pinned conversations.':'No conversations yet. Start a new chat.');const detail=selected?`<aside class="rp-panel rp-detail rp-desktop-detail rp-selected-detail"><h2>Conversation details</h2><div class="rp-detail-title">${esc(selected.title||'New conversation')}</div><p>${esc(conversationPreview(selected)||'No messages yet')}</p><div class="rp-detail-block"><small>Project / Context</small>${esc(selected.context||'No project context')}</div><div class="rp-detail-block"><small>Last updated</small>${stamp(selected.updated_at)}</div><button class="rp-button primary" data-rp-open-conv="${esc(selected.id)}">Open conversation →</button></aside>`:`<aside class="rp-panel rp-detail rp-desktop-detail"><h2>Conversation details</h2>${empty('Select a conversation to see its details.')}</aside>`;return shell('conversations','Conversations','Pick up where you left off.',`<div class="rp-tools rp-conv-tools">${search('rp-conv-search','Search conversations',s.query)}${filters('conversationFilters',[['all','All'],['pinned','Pinned'],['archived','Archived']],s.filter)}<select class="rp-select" id="rp-conv-sort" aria-label="Sort conversations"><option value="recent" ${s.sort==='recent'?'selected':''}>Most recent</option><option value="oldest" ${s.sort==='oldest'?'selected':''}>Oldest</option><option value="title" ${s.sort==='title'?'selected':''}>Title A–Z</option></select></div><div class="rp-conversation-layout"><section class="rp-list">${cards}</section>${detail}</div>`,true)}
  function bindConversations(){const s=state.conversations;$('rp-conv-search')?.addEventListener('input',e=>{setQuery('conversations','rp-conv-search',e.target.value)});$('rp-conv-sort')?.addEventListener('change',e=>{s.sort=e.target.value;render('conversations',false)});document.querySelectorAll('[data-rp-conv]').forEach(b=>b.onclick=()=>{s.selected=b.dataset.rpConv;if(matchMedia('(max-width:760px)').matches&&!preview())window.openConversation(s.selected).catch(e=>showToast(e.message));else render('conversations',false)});document.querySelectorAll('[data-rp-open-conv]').forEach(b=>b.onclick=()=>preview()?showToast('Preview only — this sample conversation is not saved.'):window.openConversation(b.dataset.rpOpenConv).catch(e=>showToast(e.message)));document.querySelectorAll('[data-rp-pin]').forEach(b=>b.onclick=async()=>{if(preview()){showToast('Preview only — changes are not saved.');return}try{await window.updateSidebarPin('chat:'+b.dataset.rpPin,b.getAttribute('aria-pressed')!=='true');await loadConversations()}catch(e){showToast(e.message)}});document.querySelectorAll('[data-rp-archive]').forEach(b=>b.onclick=async()=>{if(preview()){showToast('Preview only — changes are not saved.');return}if(!confirm('Archive this conversation?'))return;try{await api('/conversations/'+encodeURIComponent(b.dataset.rpArchive)+'/archive',{method:'POST',body:'{}'});await loadConversations();showToast('Conversation archived')}catch(e){showToast(e.message)}})}
  async function loadMemory(){const s=state.memory,epoch=++s.epoch;if(preview())s.rows=demoMemoryRows();else{const [result,prefs,projects]=await Promise.all([api('/memory?limit=100'),api('/memory/preferences'),api('/projects?status=all')]);if(epoch!==s.epoch)return;s.rows=Array.isArray(result.memories)?result.memories:[];s.prefs=prefs;s.projects=Array.isArray(projects.projects)?projects.projects:[]}render('memory')}
