  function memoryForm(item=null){if(preview()){showToast('Preview only — sample memories are not saved.');return}let dialog=$('rp-memory-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='rp-memory-dialog';dialog.className='rp-add-dialog';document.body.append(dialog)}dialog.innerHTML=`<form><header><h2>${item?'Edit memory':'Add memory'}</h2><button type="button" class="rp-icon-button" data-close aria-label="Close">×</button></header><label>Title<input name="subject" required maxlength="240" value="${esc(item?.subject||'')}"></label><label>What should Vishnu remember?<textarea name="content" required maxlength="20000" rows="5">${esc(item?.content||'')}</textarea></label><label>Category<select name="type"><option value="note" ${item?.type==='note'?'selected':''}>Note</option><option value="preference" ${item?.type==='preference'?'selected':''}>Preference</option><option value="project" ${item?.type==='project'?'selected':''}>Project</option><option value="work" ${item?.type==='work'?'selected':''}>Work</option></select></label><label>Scope<select name="scope"><option value="personal">Personal memory</option><option value="project">Project memory</option></select></label><label class="rp-project-memory-field">Project<select name="project_id"><option value="">Choose a project</option>${state.memory.projects.map(project=>`<option value="${esc(project.id)}">${esc(project.name)}</option>`).join('')}</select></label><p class="rp-form-help">Project memories stay with that project and are excluded from personal memory retrieval.</p><p class="rp-form-error" role="alert" aria-live="polite"></p><footer><button type="button" class="rp-button quiet" data-close>Cancel</button><button type="submit" class="rp-button primary">${item?'Save changes':'Save memory'}</button></footer></form>`;dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.showModal();dialog.querySelector('input[name=subject]').focus();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,data=new FormData(form),subject=String(data.get('subject')||'').trim(),content=String(data.get('content')||'').trim(),type=String(data.get('type')||'note'),save=form.querySelector('[type=submit]'),err=form.querySelector('.rp-form-error');if(!subject||!content){err.textContent='Enter a title and memory content.';return}if(scope==='project'&&!project_id){err.textContent='Choose the project that owns this memory.';return}save.disabled=true;err.textContent='Saving…';try{await api(item?'/memory/'+encodeURIComponent(item.id):'/memory',{method:item?'PATCH':'POST',body:JSON.stringify(item?{subject,content,type,scope,project_id:scope==='project'?project_id:null}:{subject,content,type,scope,project_id:scope==='project'?project_id:null,source:'explicit-owner',verified:true})});dialog.close();await loadMemory();showToast(item?'Memory updated':'Memory saved')}catch(e){err.textContent=e.message||'Could not save this memory. Your entries are still here.'}finally{save.disabled=false}}}
